We'll annotate each candidate with a date sourced from the citation. Parse "date=" in cite templates when present; if missing, check for ISO date patterns near the URL; record if the date is a post date or only an access-date.

import re

DATE_FIELD_RE = re.compile(r"\bdate\s*=\s*([0-9]{4}-[0-9]{2}-[0-9]{2})")
ACCESS_DATE_RE = re.compile(r"\baccess-date\s*=\s*([0-9]{4}-[0-9]{2}-[0-9]{2})")
ISO_NEAR_URL_RE = re.compile(r"(20\d\d-08-\d\d)")

annotated = []
for c in citations:
    ref = c["ref"]
    m_date = DATE_FIELD_RE.search(ref)
    m_access = ACCESS_DATE_RE.search(ref)
    if m_date:
        annotated.append({"page": c["page"], "date": m_date.group(1), "date_type": "post_date", "urls": c["urls"]})
    elif m_access:
        annotated.append({"page": c["page"], "date": m_access.group(1), "date_type": "access_date", "urls": c["urls"]})
    else:
        m_iso = ISO_NEAR_URL_RE.search(ref)
        if m_iso:
            annotated.append({"page": c["page"], "date": m_iso.group(1), "date_type": "unknown_source", "urls": c["urls"]})
        else:
            annotated.append({"page": c["page"], "date": None, "date_type": "undated", "urls": c["urls"]})

for a in annotated:
    print(a)

